{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync, writeSync } from 'node:fs'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/

function writeAll(fd, text) {
  const buf = Buffer.from(text, 'utf8')
  let off = 0
  while (off < buf.length) {
    try {
      off += writeSync(fd, buf, off, buf.length - off)
    } catch (err) {
      if (err && (err.code === 'EAGAIN' || err.code === 'EINTR')) continue
      throw err
    }
  }
}

function fail(message) {
  writeAll(2, `error: ${message}\n`)
  process.exit(2)
}

function lineFail(lineNo, reason) {
  fail(`line ${lineNo}: ${reason}`)
}

/** An unsigned decimal integer with no sign and no redundant leading zero. */
function parseCount(text, least) {
  if (!/^(0|[1-9][0-9]*)$/.test(text)) return null
  const value = BigInt(text)
  if (value < BigInt(least)) return null
  return value
}

/**
 * A token bucket. Tokens are held scaled by the period so that partial
 * periods accumulate exactly, with no rounding at all.
 */
class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.scaledCapacity = capacity * per
  }

  create(tick) {
    return { scaled: this.scaledCapacity, tick }
  }

  advance(state, tick) {
    const elapsed = tick - state.tick
    if (elapsed > 0n) {
      state.scaled += this.refill * elapsed
      if (state.scaled > this.scaledCapacity) state.scaled = this.scaledCapacity
    }
    state.tick = tick
  }

  allows(state) {
    return state.scaled >= this.per
  }

  record(state) {
    state.scaled -= this.per
  }
}

/** A sliding window over the `span` ticks ending at the current tick. */
class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
  }

  create() {
    return { ticks: [], head: 0 }
  }

  advance(state, tick) {
    const cutoff = tick - this.span
    const ticks = state.ticks
    while (state.head < ticks.length && ticks[state.head] <= cutoff) state.head++
    if (state.head > 0 && state.head === ticks.length) {
      state.ticks = []
      state.head = 0
    }
  }

  allows(state) {
    return BigInt(state.ticks.length - state.head) < this.limit
  }

  record(state, tick) {
    state.ticks.push(tick)
  }
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'replay' && argv[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }
  const mode = argv[0]

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routeByPrefix = new Map()
  const events = []
  let sawEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const parts = line.split(/\s+/)
    const directive = parts[0]

    if (directive === 'bucket') {
      if (sawEvent) lineFail(lineNo, 'declarations must come before the first event')
      if (parts.length !== 5) lineFail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const name = parts[1]
      if (!NAME_RE.test(name)) lineFail(lineNo, `invalid policy name ${name}`)
      const capacity = parseCount(parts[2], 1)
      if (capacity === null) lineFail(lineNo, 'capacity must be an integer of at least 1')
      const refill = parseCount(parts[3], 0)
      if (refill === null) lineFail(lineNo, 'refill must be an integer of at least 0')
      const per = parseCount(parts[4], 1)
      if (per === null) lineFail(lineNo, 'per must be an integer of at least 1')
      if (policies.has(name)) lineFail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (sawEvent) lineFail(lineNo, 'declarations must come before the first event')
      if (parts.length !== 4) lineFail(lineNo, 'expected window <name> <limit> <span>')
      const name = parts[1]
      if (!NAME_RE.test(name)) lineFail(lineNo, `invalid policy name ${name}`)
      const limit = parseCount(parts[2], 0)
      if (limit === null) lineFail(lineNo, 'limit must be an integer of at least 0')
      const span = parseCount(parts[3], 1)
      if (span === null) lineFail(lineNo, 'span must be an integer of at least 1')
      if (policies.has(name)) lineFail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (sawEvent) lineFail(lineNo, 'declarations must come before the first event')
      if (parts.length < 3) lineFail(lineNo, 'expected route <prefix> <policy>...')
      const prefix = parts[1]
      if (!NAME_RE.test(prefix)) lineFail(lineNo, `invalid route prefix ${prefix}`)
      const names = parts.slice(2)
      if (routeByPrefix.has(prefix)) lineFail(lineNo, `prefix ${prefix} is routed twice`)
      for (const name of names) {
        if (!policies.has(name)) lineFail(lineNo, `unknown policy ${name}`)
      }
      const route = { prefix, names }
      routes.push(route)
      routeByPrefix.set(prefix, route)
    } else if (directive === 'event') {
      if (parts.length !== 3) lineFail(lineNo, 'expected event <tick> <key>')
      const tick = parseCount(parts[1], 0)
      if (tick === null) lineFail(lineNo, 'tick must be an integer of at least 0')
      const key = parts[2]
      if (!NAME_RE.test(key)) lineFail(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        lineFail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      sawEvent = true
      events.push({ tick, text: parts[1], key })
    } else {
      lineFail(lineNo, `unknown directive ${directive}`)
    }
  }

  // Sorting routes longest first makes prefix lookup pick the longest match.
  const ordered = routes.slice().sort((a, b) => b.prefix.length - a.prefix.length)
  const routeOfKey = new Map()
  const stateOfKey = new Map()
  const out = []
  const stats = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (const event of events) {
    const { tick, key } = event
    let route = routeOfKey.get(key)
    if (route === undefined) {
      route = null
      for (const candidate of ordered) {
        if (key.startsWith(candidate.prefix)) {
          route = candidate
          break
        }
      }
      routeOfKey.set(key, route)
    }

    let denier = null
    if (route !== null) {
      let states = stateOfKey.get(key)
      if (states === undefined) {
        states = new Map()
        stateOfKey.set(key, states)
      }
      const pairs = []
      for (const name of route.names) {
        const policy = policies.get(name)
        let state = states.get(name)
        if (state === undefined) {
          state = policy.create(tick)
          states.set(name, state)
        }
        policy.advance(state, tick)
        pairs.push([name, policy, state])
      }
      for (const [name, policy, state] of pairs) {
        if (!policy.allows(state)) {
          denier = name
          break
        }
      }
      if (denier === null) {
        for (const [, policy, state] of pairs) policy.record(state, tick)
      }
    }

    if (mode === 'replay') {
      out.push(denier === null
        ? `${event.text} ${key} allow\n`
        : `${event.text} ${key} deny ${denier}\n`)
    } else {
      let stat = stats.get(key)
      if (stat === undefined) {
        stat = { allowed: 0, denied: 0 }
        stats.set(key, stat)
      }
      if (denier === null) {
        stat.allowed++
        totalAllowed++
      } else {
        stat.denied++
        totalDenied++
      }
    }
  }

  if (mode === 'summary') {
    const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    for (const key of keys) {
      const stat = stats.get(key)
      out.push(`${key} allowed=${stat.allowed} denied=${stat.denied}\n`)
    }
    out.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  }

  writeAll(1, out.join(''))
  process.exitCode = 0
}

main()
"}

