  advance(state, tick) {
    state.lastTick = tick;
    // Forget ticks at or before (tick - span)
    const cutoff = tick - this.span;
    state.ticks = state.ticks.filter(t => t > cutoff);
  }

  allows(state) {
    return state.ticks.length < this.limit;
  }

  record(state, tick) {
    state.ticks.push(tick);
  }
}

function isValidName(str) {
  return VALID_CHARS.test(str);
}

function isValidInteger(str, min) {
  // No sign, no leading zero unless it's "0"
  if (!/^\d+$/.test(str)) return false;
  if (str.length > 1 && str[0] === '0') return false;
  const num = parseInt(str, 10);
  return num >= min;
}

async function readInput() {
  let input = '';
  for await (const chunk of stdin) {
    input += chunk;
  }
  return input;
}

function error(lineNum, message) {
  process.stderr.write(`error: line ${lineNum}: ${message}\n`);
  process.exit(2);
}

function usageError() {
  process.stderr.write('error: usage: cli.js replay|summary\n');
  process.exit(2);
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    usageError();
  }
  const mode = args[0];

  const input = await readInput();
  const lines = input.split('\n');
  // Drop empty tail that trailing newline leaves
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  const policies = {}; // name -> policy object
  const routes = []; // { prefix, policies: [name, ...] }
  const events = [];

  let firstEventLine = -1;

  for (let i = 0; i < lines.length; i++) {
    let line = lines[i].trim();

    // Ignore empty lines and comments
    if (!line || line.startsWith('#')) {
      continue;
    }

    const parts = line.split(/\s+/);
    const directive = parts[0];
    const lineNum = i + 1;

    if (directive === 'bucket') {
      if (firstEventLine !== -1) {
        error(lineNum, 'declarations must come before the first event');
      }
      if (parts.length !== 5) {
        error(lineNum, 'expected bucket <name> <capacity> <refill> <per>');
      }
      const name = parts[1];
      const capacity = parts[2];
      const refill = parts[3];
      const per = parts[4];

      if (!isValidName(name)) {
        error(lineNum, `invalid policy name ${name}`);
      }
      if (!isValidInteger(capacity, 1)) {
        error(lineNum, 'capacity must be an integer of at least 1');
      }
      if (!isValidInteger(refill, 0)) {
        error(lineNum, 'refill must be an integer of at least 0');
      }
      if (!isValidInteger(per, 1)) {
        error(lineNum, 'per must be an integer of at least 1');
      }

      if (policies[name]) {
        error(lineNum, `policy ${name} is declared twice`);
      }

      policies[name] = new TokenBucket(
        parseInt(capacity, 10),
        parseInt(refill, 10),
        parseInt(per, 10)
      );
    } else if (directive === 'window') {
      if (firstEventLine !== -1) {
        error(lineNum, 'declarations must come before the first event');
      }
      if (parts.length !== 4) {
        error(lineNum, 'expected window <name> <limit> <span>');
      }
      const name = parts[1];
      const limit = parts[2];
      const span = parts[3];

      if (!isValidName(name)) {
        error(lineNum, `invalid policy name ${name}`);
      }
      if (!isValidInteger(limit, 0)) {
        error(lineNum, 'limit must be an integer of at least 0');
      }
      if (!isValidInteger(span, 1)) {
        error(lineNum, 'span must be an integer of at least 1');
      }

      if (policies[name]) {
        error(lineNum, `policy ${name} is declared twice`);
      }

      policies[name] = new SlidingWindow(parseInt(limit, 10), parseInt(span, 10));
    } else if (directive === 'route') {
      if (firstEventLine !== -1) {
        error(lineNum, 'declarations must come before the first event');
      }
      if (parts.length < 3) {
        error(lineNum, 'expected route <prefix> <policy>...');
      }
      const prefix = parts[1];
      const policyNames = parts.slice(2);

      if (!isValidName(prefix)) {
        error(lineNum, `invalid route prefix ${prefix}`);
      }

      // Check if prefix is already routed
      if (routes.some(r => r.prefix === prefix)) {
        error(lineNum, `prefix ${prefix} is routed twice`);
      }

      // Check all policies exist
      for (const policyName of policyNames) {
        if (!policies[policyName]) {
          error(lineNum, `unknown policy ${policyName}`);
        }
      }

      routes.push({ prefix, policyNames });
    } else if (directive === 'event') {
      if (firstEventLine === -1) {
        firstEventLine = lineNum;
      }
      if (parts.length !== 3) {
        error(lineNum, 'expected event <tick> <key>');
      }
      const tick = parts[1];
      const key = parts[2];

      if (!isValidInteger(tick, 0)) {
        error(lineNum, 'tick must be an integer of at least 0');
      }
      if (!isValidName(key)) {
        error(lineNum, `invalid key ${key}`);
      }

      events.push({
        tick: parseInt(tick, 10),
        key,
        lineNum,
      });
    } else {
      error(lineNum, `unknown directive ${directive}`);
    }
  }

  // Check ticks never go backwards
  let lastTick = -1;
  for (const evt of events) {
    if (evt.tick < lastTick) {
      error(evt.lineNum, `tick ${evt.tick} is before tick ${lastTick}`);
    }
    lastTick = evt.tick;
  }

  // Now process events
  const keyStates = {}; // key -> { policyName -> state }
  const results = [];

  for (const evt of events) {
    const { tick, key } = evt;

    // Find the route for this key
    let matchingRoute = null;
    let longestPrefix = '';
    for (const route of routes) {
      if (key.startsWith(route.prefix) && route.prefix.length > longestPrefix.length) {
        matchingRoute = route;
        longestPrefix = route.prefix;
      }
    }

    // Initialize key state if needed
    if (!keyStates[key]) {
      keyStates[key] = {};
    }

    if (!matchingRoute) {
      // No route matches - always allow
      results.push({ tick, key, allow: true });
    } else {
      // Initialize states for all policies on this route
      for (const policyName of matchingRoute.policyNames) {
        const policy = policies[policyName];
        if (!keyStates[key][policyName]) {
          keyStates[key][policyName] = policy.createState();
        }
      }

      // Advance all policies to this tick
      for (const policyName of matchingRoute.policyNames) {
        const policy = policies[policyName];
        const state = keyStates[key][policyName];
        policy.advance(state, tick);
      }

      // Ask all policies
      let allowed = true;
      let denyingPolicy = null;
      for (const policyName of matchingRoute.policyNames) {
        const policy = policies[policyName];
        const state = keyStates[key][policyName];

        if (!policy.allows(state)) {
          if (!denyingPolicy) {
            denyingPolicy = policyName;
          }
          allowed = false;
        }
      }

      // Record on all policies only if all allow
      if (allowed) {
        for (const policyName of matchingRoute.policyNames) {
          const policy = policies[policyName];
          const state = keyStates[key][policyName];
          policy.record(state, tick);
        }
        results.push({ tick, key, allow: true });
      } else {
        results.push({ tick, key, allow: false, policy: denyingPolicy });
      }
    }
  }

  if (mode === 'replay') {
    for (const result of results) {
      if (result.allow) {
        process.stdout.write(`${result.tick} ${result.key} allow\n`);
      } else {
        process.stdout.write(`${result.tick} ${result.key} deny ${result.policy}\n`);
      }
    }
  } else if (mode === 'summary') {
    const keyStats = {}; // key -> { allowed, denied }

    for (const result of results) {
      if (!keyStats[result.key]) {
        keyStats[result.key] = { allowed: 0, denied: 0 };
      }
      if (result.allow) {
        keyStats[result.key].allowed++;
      } else {
        keyStats[result.key].denied++;
      }
    }

    // Sort keys
    const sortedKeys = Object.keys(keyStats).sort();
    for (const key of sortedKeys) {
      const stats = keyStats[key];
      process.stdout.write(`${key} allowed=${stats.allowed} denied=${stats.denied}\n`);
    }

    // Total
    let totalAllowed = 0;
    let totalDenied = 0;
    for (const result of results) {
      if (result.allow) {
        totalAllowed++;
      } else {
        totalDenied++;
      }
    }
    process.stdout.write(`total allowed=${totalAllowed} denied=${totalDenied}\n`);
  }

  process.exit(0);
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`);
  process.exit(2);
});

